        sb.append("<script>");
        sb.append("  let activeWidgets = {}; let telemetryData = {}; let graphData = {}; let fieldImages = {}; let frozenGraphs = {}; let draggingPath = null;");
        sb.append("  function safeId(str) { return 'id_' + str.replace(/[^a-zA-Z0-9]/g, function(s) { return s.charCodeAt(0).toString(16); }); }");
        sb.append("  function loadSessionLayout() {");
